package com.cloudinfra.sdk.http

import java.io.OutputStream
import java.net.Socket
import java.nio.charset.StandardCharsets
import java.util.concurrent.ConcurrentHashMap
import java.security.MessageDigest
import javax.net.ssl.SSLSocketFactory

data class AuditEntry(
    val timestamp: Long,
    val requestId: String,
    val method: String,
    val path: String,
    val contentLength: Int,
    val transferEncoding: String?
)

class AuditLogger {
    private val entries = ConcurrentHashMap<String, AuditEntry>()

    fun log(entry: AuditEntry) {
        entries[entry.requestId] = entry
    }

    fun getEntry(requestId: String): AuditEntry? = entries[requestId]
}

class HttpRequestBuilder(
    private val method: String,
    private val path: String,
    private val host: String
) {
    private val headers = mutableMapOf<String, String>()
    private var body: ByteArray? = null
    private var useChunked: Boolean = false

    fun header(name: String, value: String): HttpRequestBuilder {
        headers[name.lowercase().trim()] = value.trim()
        return this
    }

    fun body(content: ByteArray, chunked: Boolean = false): HttpRequestBuilder {
        this.body = content
        this.useChunked = chunked
        return this
    }

    fun getContentLength(): Int = body?.size ?: 0
    fun getTransferEncoding(): String? = if (useChunked) "chunked" else null

    fun build(): ByteArray {
        val sb = StringBuilder()
        sb.append("$method $path HTTP/1.1\r\n")
        sb.append("Host: $host\r\n")

        // Apply content framing headers
        val contentBytes = body ?: ByteArray(0)
        if (useChunked) {
            headers["transfer-encoding"] = "chunked"
        }
        if (contentBytes.isNotEmpty()) {
            headers["content-length"] = contentBytes.size.toString()
        }

        // Write all headers
        for ((name, value) in headers) {
            sb.append("$name: $value\r\n")
        }
        sb.append("\r\n")

        val headerBytes = sb.toString().toByteArray(StandardCharsets.ISO_8859_1)

        return if (useChunked) {
            // Encode body as chunked
            val chunkedBody = encodeChunked(contentBytes)
            headerBytes + chunkedBody
        } else {
            headerBytes + contentBytes
        }
    }

    private fun encodeChunked(data: ByteArray): ByteArray {
        val sb = StringBuilder()
        sb.append("${data.size.toString(16)}\r\n")
        val prefix = sb.toString().toByteArray(StandardCharsets.ISO_8859_1)
        val suffix = "\r\n0\r\n\r\n".toByteArray(StandardCharsets.ISO_8859_1)
        return prefix + data + suffix
    }
}

class CloudInfraClient(
    private val endpoint: String,
    private val port: Int = 443,
    private val apiKey: String,
    private val auditLogger: AuditLogger = AuditLogger()
) {
    private fun generateRequestId(): String {
        val digest = MessageDigest.getInstance("SHA-256")
        val hash = digest.digest("${System.nanoTime()}-${Thread.currentThread().id}".toByteArray())
        return hash.take(16).joinToString("") { "%02x".format(it) }
    }

    fun sendRequest(
        method: String,
        path: String,
        body: ByteArray? = null,
        additionalHeaders: Map<String, String> = emptyMap(),
        useChunkedTransfer: Boolean = false
    ): ByteArray {
        val requestId = generateRequestId()
        val builder = HttpRequestBuilder(method, path, endpoint)
            .header("Authorization", "Bearer $apiKey")
            .header("X-Request-Id", requestId)
            .header("Connection", "keep-alive")

        additionalHeaders.forEach { (k, v) -> builder.header(k, v) }

        if (body != null) {
            builder.body(body, useChunkedTransfer)
        }

        // Audit logging captures the request metadata
        val auditEntry = AuditEntry(
            timestamp = System.currentTimeMillis(),
            requestId = requestId,
            method = method,
            path = path,
            contentLength = builder.getContentLength(),
            transferEncoding = builder.getTransferEncoding()
        )
        auditLogger.log(auditEntry)

        val rawRequest = builder.build()
        return transmit(rawRequest)
    }

    private fun transmit(data: ByteArray): ByteArray {
        val factory = SSLSocketFactory.getDefault() as SSLSocketFactory
        val socket: Socket = factory.createSocket(endpoint, port)
        try {
            socket.getOutputStream().write(data)
            socket.getOutputStream().flush()
            val response = socket.getInputStream().readBytes()
            return response
        } finally {
            socket.close()
        }
    }

    fun getAuditLogger(): AuditLogger = auditLogger
}

// SDK convenience functions for cloud resource management
fun CloudInfraClient.createResource(resourceType: String, payload: String): ByteArray {
    return sendRequest(
        method = "POST",
        path = "/api/v2/resources/$resourceType",
        body = payload.toByteArray(StandardCharsets.UTF_8),
        useChunkedTransfer = true
    )
}

fun CloudInfraClient.deleteResource(resourceType: String, resourceId: String): ByteArray {
    return sendRequest(
        method = "DELETE",
        path = "/api/v2/resources/$resourceType/$resourceId"
    )
}
